"""The ``procedures/{ICAO}.proc`` text format (DATA.md section 7): in-memory model, writer and a
reference reader (used by the tests and by the validation pass; the game's reader is C++,
``src/nav/Procedures.cpp``).

Format version 1 (``FORMAT flightsim-proc 1``). Plain UTF-8 text, one directive per line, tokens
separated by single spaces, ``#`` starts a whole-line comment. Floating point numbers use ``.``.
All courses and bearings are TRUE degrees; altitudes are feet MSL; speeds are knots.

    FORMAT flightsim-proc 1
    # FAA CIFP cycle 2610 (effective 2026-10-01); generated by tools/nav/cifp.py
    CYCLE 2610
    AIRPORT KOTH
    APPROACH I05-Z ILS 05 ILS Z RWY 05      # id kind runway('-' if none) title(rest of line)
    LOS LPV LNAV/VNAV LNAV                  # optional, informational
    TRANSITION RARES                         # zero or more; legs follow
    LEG IF RARES 43.64 -124.1 ALT AT 18000 IAF
    LEG AF.. (see below)
    FINAL                                    # legs of the final approach segment up to the MAP
    LEG ...
    MISSED                                   # legs after the MAP
    LEG ...
    END

    LEG <TYPE> <IDENT|-> [<LAT> <LON>] [options...]

``<TYPE>``  one of IF TF CF DF CA VA FA RF HM HA HF. ``<IDENT>`` is ``-`` when the leg has no fix
(CA, VA), and then no ``LAT LON`` follow. Options may come in any order:

    CRS <deg>                  course, true (CF CA VA FA; inbound course of HM HA HF)
    ALT <KIND> <ft> [<ft2>]    KIND = AT | ATORABOVE | ATORBELOW | BETWEEN (BETWEEN: low high)
    SPD <kt>                   speed limit
    FLYOVER                    fly-over fix (default fly-by)
    ARC <clat> <clon> <nm> <L|R>   RF: arc centre, radius, turn direction
    TURN <L|R>                 turn direction (holds; informational on other legs)
    HOLD <T|D> <value>         hold leg length: T minutes or D nautical miles
    VANG <deg>                 published vertical angle (negative = descent), informational
    WK <VOR|NDB|RWY|APT|SYN>   waypoint kind when it is not an ordinary fix
    IAF | FAF | MAP            role flags
    ORIG <ARINC type>          the leg was approximated from this ARINC 424 path terminator
    KEY=value                  reserved for later additions; readers skip any token with '='

Section order inside an approach is TRANSITION* FINAL MISSED? END. A leg that is flown in the
missed approach sits after ``MISSED``.
"""
from __future__ import annotations

import shlex
from dataclasses import dataclass, field

FORMAT_NAME = "flightsim-proc"
FORMAT_VERSION = 1

LEG_TYPES = ("IF", "TF", "CF", "DF", "CA", "VA", "FA", "RF", "HM", "HA", "HF")
ALT_KINDS = ("AT", "ATORABOVE", "ATORBELOW", "BETWEEN")
WP_KINDS = ("FIX", "VOR", "NDB", "RWY", "APT", "SYN")


@dataclass
class Fix:
    ident: str
    lat: float
    lon: float
    kind: str = "FIX"


@dataclass
class Leg:
    type: str
    fix: Fix | None = None
    crsTrue: float | None = None
    altKind: str | None = None
    alt: float = 0.0
    alt2: float = 0.0
    speedKt: int = 0
    flyOver: bool = False
    arc: tuple[float, float, float, str] | None = None  # centre lat, lon, radius NM, 'L'|'R'
    turn: str | None = None
    holdTimeMin: float | None = None
    holdDistNm: float | None = None
    vertAngleDeg: float | None = None
    flags: set = field(default_factory=set)  # IAF FAF MAP
    orig: str | None = None  # ARINC type when approximated

    @property
    def ident(self) -> str:
        return self.fix.ident if self.fix else ""


@dataclass
class Transition:
    name: str
    legs: list[Leg] = field(default_factory=list)


@dataclass
class Approach:
    id: str
    kind: str
    runway: str  # DB style ("05", "28L") or ""
    title: str
    airport: str = ""
    los: list[str] = field(default_factory=list)
    transitions: list[Transition] = field(default_factory=list)
    final: list[Leg] = field(default_factory=list)
    missed: list[Leg] = field(default_factory=list)


# --------------------------------------------------------------------------------------------
# writer
# --------------------------------------------------------------------------------------------
def _num(v: float, digits: int = 1) -> str:
    s = f"{v:.{digits}f}"
    if "." in s:
        s = s.rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s


def format_leg(leg: Leg) -> str:
    parts = ["LEG", leg.type]
    if leg.fix is None:
        parts.append("-")
    else:
        parts += [leg.fix.ident, f"{leg.fix.lat:.7f}", f"{leg.fix.lon:.7f}"]
    if leg.crsTrue is not None:
        parts += ["CRS", f"{leg.crsTrue:.1f}"]
    if leg.altKind:
        parts += ["ALT", leg.altKind, _num(leg.alt, 0)]
        if leg.altKind == "BETWEEN":
            parts.append(_num(leg.alt2, 0))
    if leg.speedKt:
        parts += ["SPD", str(int(leg.speedKt))]
    if leg.flyOver:
        parts.append("FLYOVER")
    if leg.arc is not None:
        clat, clon, rad, d = leg.arc
        parts += ["ARC", f"{clat:.7f}", f"{clon:.7f}", f"{rad:.3f}", d]
    if leg.turn:
        parts += ["TURN", leg.turn]
    if leg.holdTimeMin is not None:
        parts += ["HOLD", "T", _num(leg.holdTimeMin, 1)]
    elif leg.holdDistNm is not None:
        parts += ["HOLD", "D", _num(leg.holdDistNm, 1)]
    if leg.vertAngleDeg is not None:
        parts += ["VANG", _num(leg.vertAngleDeg, 2)]
    if leg.fix is not None and leg.fix.kind != "FIX":
        parts += ["WK", leg.fix.kind]
    for f in ("IAF", "FAF", "MAP"):
        if f in leg.flags:
            parts.append(f)
    if leg.orig:
        parts += ["ORIG", leg.orig]
    return " ".join(parts)


def write_proc(airport: str, approaches: list[Approach], cycle: str, effective: str,
               generator: str = "tools/nav/cifp.py") -> str:
    out = [f"FORMAT {FORMAT_NAME} {FORMAT_VERSION}",
           f"# FAA CIFP cycle {cycle}" + (f" (effective {effective})" if effective else "")
           + f"; generated by {generator}; US Government work, public domain",
           f"CYCLE {cycle}", f"AIRPORT {airport}"]
    for ap in approaches:
        out.append(f"APPROACH {ap.id} {ap.kind} {ap.runway or '-'} {ap.title}")
        if ap.los:
            out.append("LOS " + " ".join(ap.los))
        for tr in ap.transitions:
            out.append(f"TRANSITION {tr.name}")
            out += [format_leg(l) for l in tr.legs]
        out.append("FINAL")
        out += [format_leg(l) for l in ap.final]
        if ap.missed:
            out.append("MISSED")
            out += [format_leg(l) for l in ap.missed]
        out.append("END")
    return "\n".join(out) + "\n"


# --------------------------------------------------------------------------------------------
# reference reader
# --------------------------------------------------------------------------------------------
class ProcError(ValueError):
    pass


def parse_leg(line: str, lineNo: int = 0) -> Leg:
    t = line.split()
    where = f"line {lineNo}: " if lineNo else ""
    if len(t) < 3 or t[0] != "LEG":
        raise ProcError(where + "bad LEG line")
    if t[1] not in LEG_TYPES:
        raise ProcError(where + f"unknown leg type {t[1]}")
    leg = Leg(t[1])
    i = 3
    if t[2] != "-":
        if len(t) < 5:
            raise ProcError(where + "LEG needs ident lat lon")
        leg.fix = Fix(t[2], float(t[3]), float(t[4]))
        i = 5
    try:
        while i < len(t):
            k = t[i]
            if k == "CRS":
                leg.crsTrue = float(t[i + 1]); i += 2
            elif k == "ALT":
                leg.altKind = t[i + 1]
                if leg.altKind not in ALT_KINDS:
                    raise ProcError(where + f"unknown ALT kind {leg.altKind}")
                leg.alt = float(t[i + 2]); i += 3
                if leg.altKind == "BETWEEN":
                    leg.alt2 = float(t[i]); i += 1
            elif k == "SPD":
                leg.speedKt = int(float(t[i + 1])); i += 2
            elif k == "FLYOVER":
                leg.flyOver = True; i += 1
            elif k == "ARC":
                leg.arc = (float(t[i + 1]), float(t[i + 2]), float(t[i + 3]), t[i + 4]); i += 5
            elif k == "TURN":
                leg.turn = t[i + 1]; i += 2
            elif k == "HOLD":
                v = float(t[i + 2])
                if t[i + 1] == "T":
                    leg.holdTimeMin = v
                else:
                    leg.holdDistNm = v
                i += 3
            elif k == "VANG":
                leg.vertAngleDeg = float(t[i + 1]); i += 2
            elif k == "WK":
                if leg.fix is not None:
                    leg.fix.kind = t[i + 1]
                i += 2
            elif k in ("IAF", "FAF", "MAP"):
                leg.flags.add(k); i += 1
            elif k == "ORIG":
                leg.orig = t[i + 1]; i += 2
            elif "=" in k:
                i += 1
            else:
                raise ProcError(where + f"unknown option {k}")
    except (IndexError, ValueError) as e:
        if isinstance(e, ProcError):
            raise
        raise ProcError(where + f"malformed option near '{t[min(i, len(t) - 1)]}'") from e
    return leg


def parse_proc(text: str) -> tuple[dict, list[Approach]]:
    """Returns ({'cycle':..., 'airport':...}, approaches). Raises ProcError."""
    meta = {"cycle": "", "airport": ""}
    approaches: list[Approach] = []
    cur: Approach | None = None
    seg: list[Leg] | None = None
    sawFormat = False
    for n, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key = line.split(None, 1)[0]
        if not sawFormat:
            t = line.split()
            if t[0] != "FORMAT" or len(t) < 3:
                raise ProcError("line %d: first directive must be FORMAT" % n)
            if t[1] != FORMAT_NAME or int(t[2]) != FORMAT_VERSION:
                raise ProcError(f"unsupported format {t[1]} {t[2]}")
            sawFormat = True
            continue
        if key == "CYCLE":
            meta["cycle"] = line.split()[1]
        elif key == "AIRPORT":
            meta["airport"] = line.split()[1]
        elif key == "APPROACH":
            t = line.split(None, 4)
            if len(t) < 4:
                raise ProcError(f"line {n}: bad APPROACH")
            cur = Approach(t[1], t[2], "" if t[3] == "-" else t[3], t[4] if len(t) > 4 else "",
                           meta["airport"])
            approaches.append(cur)
            seg = None
        elif cur is None:
            if key in ("LOS", "TRANSITION", "FINAL", "MISSED", "LEG", "END"):
                raise ProcError(f"line {n}: '{key}' outside an approach")
            # unknown directive between approaches: ignored for forward compatibility
        elif key == "LOS":
            cur.los = line.split()[1:]
        elif key == "TRANSITION":
            tr = Transition(line.split()[1] if len(line.split()) > 1 else "")
            cur.transitions.append(tr)
            seg = tr.legs
        elif key == "FINAL":
            seg = cur.final
        elif key == "MISSED":
            seg = cur.missed
        elif key == "END":
            cur = None
            seg = None
        elif key == "LEG":
            if seg is None:
                raise ProcError(f"line {n}: LEG before TRANSITION/FINAL/MISSED")
            seg.append(parse_leg(line, n))
        else:
            pass  # unknown directive: ignored for forward compatibility
    if not sawFormat:
        raise ProcError("empty file")
    return meta, approaches
